    void (*drop)(void *p);
    bool (*eq)(const void *a, const void *b);
    uint64_t (*hash)(const void *p);
    int (*cmp)(const void *a, const void *b);
    void (*fmt)(mxy_buf *b, const void *p, int nested);
    const char *name;
