static const char runtime_src[] = "/* moxy runtime: core (reference counts, allocation, panics) */\n" "#include <limits.h>\n" "#include <stdarg.h>\n" "#include <stdbool.h>\n" "#include <stddef.h>\n" "#include <stdint.h>\n" "#include <stdio.h>\n" "#include <stdlib.h>\n" "#include <string.h>\n" "#ifdef MXY_THREADS\n" "#include <pthread.h>\n" "#endif\n" "\n" "#define MXY_FN static __attribute__((unused))\n" "#define MXY_INLINE static inline __attribute__((unused))\n" "#define MXY_NORETURN __attribute__((noreturn))\n" "\n" "/* reference counts below zero mark immortal values (literals, statics) */\n" "MXY_INLINE void mxy_rc_inc(int64_t *rc) {\n" "    if (__atomic_load_n(rc, __ATOMIC_RELAXED) >= 0) __atomic_fetch_add(rc, 1, __ATOMIC_RELAXED);\n" "}\n" "\n" "MXY_INLINE int mxy_rc_dec(int64_t *rc) {\n" "    if (__atomic_load_n(rc, __ATOMIC_RELAXED) < 0) return 0;\n" "    return __atomic_sub_fetch(rc, 1, __ATOMIC_ACQ_REL) == 0;\n" "}\n" "\n" "MXY_INLINE int64_t mxy_rc_load(int64_t *rc) { return __atomic_load_n(rc, __ATOMIC_ACQUIRE); }\n" "\n" "MXY_FN MXY_NORETURN void mxy_panic(const char *where, const char *fmt, ...) {\n" "    fflush(stdout);\n" "    va_list ap;\n" "    va_start(ap, fmt);\n" "    fputs(\"panic: \", stderr);\n" "    vfprintf(stderr, fmt, ap);\n" "    va_end(ap);\n" "    if (where) fprintf(stderr, \"\\n  at %s\", where);\n" "    fputc('\\n', stderr);\n" "    exit(101);\n" "}\n" "\n" "MXY_FN void *mxy_alloc(size_t n) {\n" "    void *p = malloc(n ? n : 1);\n" "    if (!p) mxy_panic(NULL, \"out of memory\");\n" "    return p;\n" "}\n" "\n" "MXY_FN void *mxy_zalloc(size_t n) {\n" "    void *p = calloc(1, n ? n : 1);\n" "    if (!p) mxy_panic(NULL, \"out of memory\");\n" "    return p;\n" "}\n" "\n" "MXY_FN void *mxy_realloc(void *p, size_t n) {\n" "    void *q = realloc(p, n ? n : 1);\n" "    if (!q) mxy_panic(NULL, \"out of memory\");\n" "    return q;\n" "}\n" "\n" "MXY_INLINE uint64_t mxy_hash_u64(uint64_t x) {\n" "    x += 0x9e3779b97f4a7c15ull;\n" "    x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ull;\n" "    x = (x ^ (x >> 27)) * 0x94d049bb133111ebull;\n" "    return x ^ (x >> 31);\n" "}\n" "\n" "MXY_INLINE uint64_t mxy_hash_bytes(const void *p, size_t n) {\n" "    const unsigned char *s = (const unsigned char *)p;\n" "    uint64_t h = 1469598103934665603ull;\n" "    for (size_t i = 0; i < n; i++) h = (h ^ s[i]) * 1099511628211ull;\n" "    return h;\n" "}\n" "\n" "/* growable byte buffer used for formatting */\n" "typedef struct {\n" "    char *data;\n" "    int64_t len;\n" "    int64_t cap;\n" "} mxy_buf;\n" "\n" "MXY_FN void mxy_buf_reserve(mxy_buf *b, int64_t extra) {\n" "    if (b->len + extra + 1 <= b->cap) return;\n" "    int64_t cap = b->cap ? b->cap : 64;\n" "    while (cap < b->len + extra + 1) cap *= 2;\n" "    b->data = (char *)mxy_realloc(b->data, (size_t)cap);\n" "    b->cap = cap;\n" "}\n" "\n" "MXY_FN void mxy_buf_put(mxy_buf *b, const char *s, int64_t n) {\n" "    mxy_buf_reserve(b, n);\n" "    memcpy(b->data + b->len, s, (size_t)n);\n" "    b->len += n;\n" "    b->data[b->len] = '\\0';\n" "}\n" "\n" "MXY_FN void mxy_buf_puts(mxy_buf *b, const char *s) { mxy_buf_put(b, s ? s : \"(null)\", (int64_t)strlen(s ? s : \"(null)\")); }\n" "\n" "MXY_FN void mxy_buf_putc(mxy_buf *b, char c) { mxy_buf_put(b, &c, 1); }\n" "\n" "MXY_FN void mxy_buf_printf(mxy_buf *b, const char *fmt, ...) {\n" "    va_list ap, cp;\n" "    va_start(ap, fmt);\n" "    va_copy(cp, ap);\n" "    int n = vsnprintf(NULL, 0, fmt, cp);\n" "    va_end(cp);\n" "    if (n > 0) {\n" "        mxy_buf_reserve(b, n);\n" "        vsnprintf(b->data + b->len, (size_t)n + 1, fmt, ap);\n" "        b->len += n;\n" "    }\n" "    va_end(ap);\n" "}\n" "\n" "/* value witness: how to copy, drop, compare, hash and print one value */\n" "typedef struct mxy_vw {\n" "    size_t size;\n" "    void (*copy)(void *dst, const void *src);\n" "    void (*drop)(void *p);\n" "    bool (*eq)(const void *a, const void *b);\n" "    uint64_t (*hash)(const void *p);\n" "    int (*cmp)(const void *a, const void *b);\n" "    void (*fmt)(mxy_buf *b, const void *p, int nested);\n" "    const char *name;\n" "} mxy_vw;\n" "\n" "MXY_INLINE void mxy_vw_copy(const mxy_vw *vw, void *dst, const void *src) {\n" "    if (vw->copy) vw->copy(dst, src);\n" "    else memcpy(dst, src, vw->size);\n" "}\n" "\n" "MXY_INLINE void mxy_vw_drop(const mxy_vw *vw, void *p) {\n" "    if (vw->drop) vw->drop(p);\n" "}\n" "\n" "MXY_FN bool mxy_vw_eq(const mxy_vw *vw, const void *a, const void *b) {\n" "    if (vw->eq) return vw->eq(a, b);\n" "    return memcmp(a, b, vw->size) == 0;\n" "}\n" "\n" "MXY_FN uint64_t mxy_vw_hash(const mxy_vw *vw, const void *p) {\n" "    if (vw->hash) return vw->hash(p);\n" "    return mxy_hash_bytes(p, vw->size);\n" "}\n" "\n" "MXY_FN void mxy_vw_fmt(const mxy_vw *vw, mxy_buf *b, const void *p, int nested) {\n" "    if (vw->fmt) vw->fmt(b, p, nested);\n" "    else mxy_buf_printf(b, \"<%s>\", vw->name ? vw->name : \"value\");\n" "}\n" "\n" "/* moxy runtime: strings (immutable, reference counted, NUL terminated) */\n" "typedef const char *mxy_str;\n" "\n" "typedef struct {\n" "    int64_t rc;\n" "    int64_t len;\n" "} mxy_strhdr;\n" "\n" "#define MXY_STRHDR(s) ((mxy_strhdr *)(s) - 1)\n" "#define MXY_LIT(name, text) static struct { mxy_strhdr h; char s[sizeof(text)]; } name __attribute__((unused)) = {{-1, (int64_t)sizeof(text) - 1}, text}\n" "\n" "MXY_FN char *mxy_str_alloc(int64_t len) {\n" "    mxy_strhdr *h = (mxy_strhdr *)mxy_alloc(sizeof(mxy_strhdr) + (size_t)len + 1);\n" "    h->rc = 1;\n" "    h->len = len;\n" "    char *s = (char *)(h + 1);\n" "    s[len] = '\\0';\n" "    return s;\n" "}\n" "\n" "MXY_FN mxy_str mxy_str_fromn(const char *p, int64_t n) {\n" "    char *s = mxy_str_alloc(n);\n" "    if (n) memcpy(s, p, (size_t)n);\n" "    return s;\n" "}\n" "\n" "MXY_FN mxy_str mxy_str_from(const char *p) {\n" "    if (!p) return NULL;\n" "    return mxy_str_fromn(p, (int64_t)strlen(p));\n" "}\n" "\n" "/* takes ownership of the buffer's bytes */\n" "MXY_FN mxy_str mxy_str_from_buf(mxy_buf *b) {\n" "    mxy_str s = mxy_str_fromn(b->data ? b->data : \"\", b->len);\n" "    free(b->data);\n" "    b->data = NULL;\n" "    b->len = b->cap = 0;\n" "    return s;\n" "}\n" "\n" "MXY_INLINE mxy_str mxy_str_retain(mxy_str s) {\n" "    if (s) mxy_rc_inc(&MXY_STRHDR(s)->rc);\n" "    return s;\n" "}\n" "\n" "/* literals are immortal (rc < 0) and never reach free(); gcc cannot see through the atomic check */\n" "#if defined(__GNUC__) && !defined(__clang__)\n" "#pragma GCC diagnostic push\n" "#pragma GCC diagnostic ignored \"-Wfree-nonheap-object\"\n" "#endif\n" "MXY_INLINE void mxy_str_release(mxy_str s) {\n" "    if (s && mxy_rc_dec(&MXY_STRHDR(s)->rc)) free(MXY_STRHDR(s));\n" "}\n" "#if defined(__GNUC__) && !defined(__clang__)\n" "#pragma GCC diagnostic pop\n" "#endif\n" "\n" "MXY_INLINE int64_t mxy_str_len(mxy_str s) { return s ? MXY_STRHDR(s)->len : 0; }\n" "\n" "MXY_FN mxy_str mxy_str_concat(mxy_str a, mxy_str b) {\n" "    int64_t la = mxy_str_len(a), lb = mxy_str_len(b);\n" "    char *s = mxy_str_alloc(la + lb);\n" "    if (la) memcpy(s, a, (size_t)la);\n" "    if (lb) memcpy(s + la, b, (size_t)lb);\n" "    return s;\n" "}\n" "\n" "MXY_FN bool mxy_str_eq(mxy_str a, mxy_str b) {\n" "    if (a == b) return true;\n" "    if (!a || !b) return false;\n" "    int64_t n = mxy_str_len(a);\n" "    return n == mxy_str_len(b) && memcmp(a, b, (size_t)n) == 0;\n" "}\n" "\n" "MXY_FN int mxy_str_cmp(mxy_str a, mxy_str b) {\n" "    int64_t la = mxy_str_len(a), lb = mxy_str_len(b);\n" "    int64_t n = la < lb ? la : lb;\n" "    int c = n ? memcmp(a, b, (size_t)n) : 0;\n" "    if (c) return c < 0 ? -1 : 1;\n" "    return (la > lb) - (la < lb);\n" "}\n" "\n" "MXY_FN char mxy_str_at(mxy_str s, int64_t i, const char *loc) {\n" "    int64_t n = mxy_str_len(s);\n" "    if (i < 0 || i >= n) mxy_panic(loc, \"string index %lld out of range (length %lld)\", (long long)i, (long long)n);\n" "    return s[i];\n" "}\n" "\n" "MXY_FN mxy_str mxy_str_slice(mxy_str s, int64_t a, int64_t b, const char *loc) {\n" "    int64_t n = mxy_str_len(s);\n" "    if (a < 0 || b < a || b > n)\n" "        mxy_panic(loc, \"string slice [%lld, %lld) out of range (length %lld)\", (long long)a, (long long)b, (long long)n);\n" "    return mxy_str_fromn(s + a, b - a);\n" "}\n" "\n" "MXY_FN int64_t mxy_str_find(mxy_str s, mxy_str sub) {\n" "    if (!s || !sub) return sub && !*sub ? 0 : -1;\n" "    const char *p = strstr(s, sub);\n" "    return p ? (int64_t)(p - s) : -1;\n" "}\n" "\n" "MXY_FN bool mxy_str_contains(mxy_str s, mxy_str sub) { return mxy_str_find(s, sub) >= 0; }\n" "\n" "MXY_FN bool mxy_str_starts_with(mxy_str s, mxy_str p) {\n" "    int64_t n = mxy_str_len(p);\n" "    return n <= mxy_str_len(s) && (n == 0 || memcmp(s, p, (size_t)n) == 0);\n" "}\n" "\n" "MXY_FN bool mxy_str_ends_with(mxy_str s, mxy_str p) {\n" "    int64_t n = mxy_str_len(p), m = mxy_str_len(s);\n" "    return n <= m && (n == 0 || memcmp(s + m - n, p, (size_t)n) == 0);\n" "}\n" "\n" "MXY_FN mxy_str mxy_str_upper(mxy_str s) {\n" "    int64_t n = mxy_str_len(s);\n" "    char *r = mxy_str_alloc(n);\n" "    for (int64_t i = 0; i < n; i++) r[i] = (char)((s[i] >= 'a' && s[i] <= 'z') ? s[i] - 32 : s[i]);\n" "    return r;\n" "}\n" "\n" "MXY_FN mxy_str mxy_str_lower(mxy_str s) {\n" "    int64_t n = mxy_str_len(s);\n" "    char *r = mxy_str_alloc(n);\n" "    for (int64_t i = 0; i < n; i++) r[i] = (char)((s[i] >= 'A' && s[i] <= 'Z') ? s[i] + 32 : s[i]);\n" "    return r;\n" "}\n" "\n" "MXY_INLINE int mxy_is_space(char c) { return c == ' ' || c == '\\t' || c == '\\n' || c == '\\r' || c == '\\f' || c == '\\v'; }\n" "\n" "MXY_FN mxy_str mxy_str_trim(mxy_str s) {\n" "    int64_t a = 0, b = mxy_str_len(s);\n" "    while (a < b && mxy_is_space(s[a])) a++;\n" "    while (b > a && mxy_is_space(s[b - 1])) b--;\n" "    return mxy_str_fromn(s ? s + a : \"\", b - a);\n" "}\n" "\n" "MXY_FN mxy_str mxy_str_replace(mxy_str s, mxy_str from, mxy_str to) {\n" "    int64_t n = mxy_str_len(s), fl = mxy_str_len(from), tl = mxy_str_len(to);\n" "    if (!fl) return mxy_str_retain(s ? s : mxy_str_fromn(\"\", 0));\n" "    mxy_buf b = {0};\n" "    for (int64_t i = 0; i < n;) {\n" "        if (i + fl <= n && memcmp(s + i, from, (size_t)fl) == 0) {\n" "            mxy_buf_put(&b, to ? to : \"\", tl);\n" "            i += fl;\n" "        } else {\n" "            mxy_buf_putc(&b, s[i++]);\n" "        }\n" "    }\n" "    return mxy_str_from_buf(&b);\n" "}\n" "\n" "MXY_FN mxy_str mxy_str_repeat(mxy_str s, int64_t times) {\n" "    int64_t n = mxy_str_len(s);\n" "    if (times < 0) times = 0;\n" "    char *r = mxy_str_alloc(n * times);\n" "    for (int64_t i = 0; i < times; i++) memcpy(r + i * n, s, (size_t)n);\n" "    return r;\n" "}\n" "\n" "MXY_FN bool mxy_str_parse_long(mxy_str s, long *out) {\n" "    if (!s || !*s) return false;\n" "    char *end;\n" "    long v = strtol(s, &end, 10);\n" "    while (*end && mxy_is_space(*end)) end++;\n" "    if (*end) return false;\n" "    *out = v;\n" "    return true;\n" "}\n" "\n" "MXY_FN bool mxy_str_parse_double(mxy_str s, double *out) {\n" "    if (!s || !*s) return false;\n" "    char *end;\n" "    double v = strtod(s, &end);\n" "    while (*end && mxy_is_space(*end)) end++;\n" "    if (*end) return false;\n" "    *out = v;\n" "    return true;\n" "}\n" "/* moxy runtime: formatting and value witnesses for builtin types */\n" "MXY_FN void mxy_fmt_double(mxy_buf *b, double v) {\n" "    char tmp[64];\n" "    if (v != v) {\n" "        mxy_buf_puts(b, \"nan\");\n" "        return;\n" "    }\n" "    if (v == 1.0 / 0.0 || v == -1.0 / 0.0) {\n" "        mxy_buf_puts(b, v > 0 ? \"inf\" : \"-inf\");\n" "        return;\n" "    }\n" "    for (int prec = 1; prec <= 17; prec++) {\n" "        snprintf(tmp, sizeof(tmp), \"%.*g\", prec, v);\n" "        if (strtod(tmp, NULL) == v) break;\n" "    }\n" "    mxy_buf_puts(b, tmp);\n" "    if (!strpbrk(tmp, \".eni\")) mxy_buf_puts(b, \".0\");\n" "}\n" "\n" "MXY_FN void mxy_fmt_float(mxy_buf *b, float v) {\n" "    char tmp[64];\n" "    if (v != v) {\n" "        mxy_buf_puts(b, \"nan\");\n" "        return;\n" "    }\n" "    for (int prec = 1; prec <= 9; prec++) {\n" "        snprintf(tmp, sizeof(tmp), \"%.*g\", prec, (double)v);\n" "        if (strtof(tmp, NULL) == v) break;\n" "    }\n" "    mxy_buf_puts(b, tmp);\n" "    if (!strpbrk(tmp, \".eni\")) mxy_buf_puts(b, \".0\");\n" "}\n" "\n" "MXY_FN void mxy_fmt_quoted(mxy_buf *b, const char *s, int64_t n, char q) {\n" "    mxy_buf_putc(b, q);\n" "    for (int64_t i = 0; i < n; i++) {\n" "        char c = s[i];\n" "        switch (c) {\n" "        case '\\n': mxy_buf_puts(b, \"\\\\n\"); break;\n" "        case '\\t': mxy_buf_puts(b, \"\\\\t\"); break;\n" "        case '\\r': mxy_buf_puts(b, \"\\\\r\"); break;\n" "        case '\\\\': mxy_buf_puts(b, \"\\\\\\\\\"); break;\n" "        default:\n" "            if (c == q) mxy_buf_putc(b, '\\\\');\n" "            mxy_buf_putc(b, c);\n" "        }\n" "    }\n" "    mxy_buf_putc(b, q);\n" "}\n" "\n" "/* typed formatters (by value) used by print and interpolation */\n" "MXY_FN void mxy_fmtv_bool(mxy_buf *b, int v) { mxy_buf_puts(b, v ? \"true\" : \"false\"); }\n" "MXY_FN void mxy_fmtv_char(mxy_buf *b, char v) { mxy_buf_putc(b, v); }\n" "MXY_FN void mxy_fmtv_schar(mxy_buf *b, signed char v) { mxy_buf_printf(b, \"%d\", (int)v); }\n" "MXY_FN void mxy_fmtv_uchar(mxy_buf *b, unsigned char v) { mxy_buf_printf(b, \"%u\", (unsigned)v); }\n" "MXY_FN void mxy_fmtv_short(mxy_buf *b, short v) { mxy_buf_printf(b, \"%d\", (int)v); }\n" "MXY_FN void mxy_fmtv_ushort(mxy_buf *b, unsigned short v) { mxy_buf_printf(b, \"%u\", (unsigned)v); }\n" "MXY_FN void mxy_fmtv_int(mxy_buf *b, int v) { mxy_buf_printf(b, \"%d\", v); }\n" "MXY_FN void mxy_fmtv_uint(mxy_buf *b, unsigned v) { mxy_buf_printf(b, \"%u\", v); }\n" "MXY_FN void mxy_fmtv_long(mxy_buf *b, long v) { mxy_buf_printf(b, \"%ld\", v); }\n" "MXY_FN void mxy_fmtv_ulong(mxy_buf *b, unsigned long v) { mxy_buf_printf(b, \"%lu\", v); }\n" "MXY_FN void mxy_fmtv_llong(mxy_buf *b, long long v) { mxy_buf_printf(b, \"%lld\", v); }\n" "MXY_FN void mxy_fmtv_ullong(mxy_buf *b, unsigned long long v) { mxy_buf_printf(b, \"%llu\", v); }\n" "MXY_FN void mxy_fmtv_float(mxy_buf *b, float v) { mxy_fmt_float(b, v); }\n" "MXY_FN void mxy_fmtv_double(mxy_buf *b, double v) { mxy_fmt_double(b, v); }\n" "MXY_FN void mxy_fmtv_ldouble(mxy_buf *b, long double v) { mxy_fmt_double(b, (double)v); }\n" "MXY_FN void mxy_fmtv_cstr(mxy_buf *b, const char *v) { mxy_buf_puts(b, v); }\n" "MXY_FN void mxy_fmtv_str(mxy_buf *b, mxy_str v) { if (v) mxy_buf_put(b, v, mxy_str_len(v)); else mxy_buf_puts(b, \"null\"); }\n" "MXY_FN void mxy_fmtv_ptr(mxy_buf *b, const void *v) {\n" "    if (v) mxy_buf_printf(b, \"%p\", v);\n" "    else mxy_buf_puts(b, \"null\");\n" "}\n" "\n" "/* print values of C types Moxy cannot see, chosen by the C compiler */\n" "#define MXY_FMT_ANY(b, x) _Generic((x),                          \\\n" "    _Bool: mxy_fmtv_bool, char: mxy_fmtv_char,                    \\\n" "    signed char: mxy_fmtv_schar, unsigned char: mxy_fmtv_uchar,   \\\n" "    short: mxy_fmtv_short, unsigned short: mxy_fmtv_ushort,       \\\n" "    int: mxy_fmtv_int, unsigned int: mxy_fmtv_uint,               \\\n" "    long: mxy_fmtv_long, unsigned long: mxy_fmtv_ulong,           \\\n" "    long long: mxy_fmtv_llong, unsigned long long: mxy_fmtv_ullong, \\\n" "    float: mxy_fmtv_float, double: mxy_fmtv_double,               \\\n" "    long double: mxy_fmtv_ldouble, char *: mxy_fmtv_cstr,          \\\n" "    const char *: mxy_fmtv_cstr, default: mxy_fmtv_ptr)(b, x)\n" "\n" "MXY_FN void mxy_buf_flush(mxy_buf *b, FILE *f) {\n" "    if (b->len) fwrite(b->data, 1, (size_t)b->len, f);\n" "    free(b->data);\n" "    b->data = NULL;\n" "    b->len = b->cap = 0;\n" "}\n" "\n" "#define MXY_PRIM_VW(NAME, T, FMTEXPR)                                                     \\\n" "    MXY_FN bool mxy_eq_##NAME(const void *a, const void *b) { return *(const T *)a == *(const T *)b; } \\\n" "    MXY_FN uint64_t mxy_hash_##NAME(const void *p) { return mxy_hash_u64((uint64_t) * (const T *)p); } \\\n" "    MXY_FN int mxy_cmp_##NAME(const void *a, const void *b) {                              \\\n" "        T x = *(const T *)a, y = *(const T *)b;                                             \\\n" "        return (x > y) - (x < y);                                                          \\\n" "    }                                                                                      \\\n" "    MXY_FN void mxy_fmtp_##NAME(mxy_buf *b, const void *p, int nested) {                   \\\n" "        (void)nested;                                                                      \\\n" "        T v = *(const T *)p;                                                               \\\n" "        FMTEXPR;                                                                           \\\n" "    }                                                                                      \\\n" "    static const mxy_vw mxy_vw_##NAME __attribute__((unused)) = {                          \\\n" "        sizeof(T), NULL, NULL, mxy_eq_##NAME, mxy_hash_##NAME, mxy_cmp_##NAME, mxy_fmtp_##NAME, #NAME};\n" "\n" "MXY_PRIM_VW(bool, bool, mxy_fmtv_bool(b, v))\n" "MXY_PRIM_VW(char, char, if (nested) mxy_fmt_quoted(b, &v, 1, '\\''); else mxy_buf_putc(b, v))\n" "MXY_PRIM_VW(schar, signed char, mxy_fmtv_schar(b, v))\n" "MXY_PRIM_VW(uchar, unsigned char, mxy_fmtv_uchar(b, v))\n" "MXY_PRIM_VW(short, short, mxy_fmtv_short(b, v))\n" "MXY_PRIM_VW(ushort, unsigned short, mxy_fmtv_ushort(b, v))\n" "MXY_PRIM_VW(int, int, mxy_fmtv_int(b, v))\n" "MXY_PRIM_VW(uint, unsigned int, mxy_fmtv_uint(b, v))\n" "MXY_PRIM_VW(long, long, mxy_fmtv_long(b, v))\n" "MXY_PRIM_VW(ulong, unsigned long, mxy_fmtv_ulong(b, v))\n" "MXY_PRIM_VW(llong, long long, mxy_fmtv_llong(b, v))\n" "MXY_PRIM_VW(ullong, unsigned long long, mxy_fmtv_ullong(b, v))\n" "MXY_PRIM_VW(float, float, mxy_fmtv_float(b, v))\n" "MXY_PRIM_VW(double, double, mxy_fmtv_double(b, v))\n" "MXY_PRIM_VW(ldouble, long double, mxy_fmtv_ldouble(b, v))\n" "\n" "MXY_FN bool mxy_eq_ptr(const void *a, const void *b) { return *(void *const *)a == *(void *const *)b; }\n" "MXY_FN uint64_t mxy_hash_ptr(const void *p) { return mxy_hash_u64((uint64_t)(uintptr_t) * (void *const *)p); }\n" "MXY_FN int mxy_cmp_ptr(const void *a, const void *b) {\n" "    uintptr_t x = (uintptr_t) * (void *const *)a, y = (uintptr_t) * (void *const *)b;\n" "    return (x > y) - (x < y);\n" "}\n" "MXY_FN void mxy_fmtp_ptr(mxy_buf *b, const void *p, int nested) {\n" "    (void)nested;\n" "    mxy_fmtv_ptr(b, *(void *const *)p);\n" "}\n" "static const mxy_vw mxy_vw_ptr __attribute__((unused)) = {sizeof(void *), NULL, NULL, mxy_eq_ptr, mxy_hash_ptr, mxy_cmp_ptr, mxy_fmtp_ptr, \"pointer\"};\n" "\n" "MXY_FN void mxy_copy_str(void *dst, const void *src) { *(mxy_str *)dst = mxy_str_retain(*(const mxy_str *)src); }\n" "MXY_FN void mxy_drop_str(void *p) { mxy_str_release(*(mxy_str *)p); }\n" "MXY_FN bool mxy_eq_str(const void *a, const void *b) { return mxy_str_eq(*(const mxy_str *)a, *(const mxy_str *)b); }\n" "MXY_FN uint64_t mxy_hash_str(const void *p) {\n" "    mxy_str s = *(const mxy_str *)p;\n" "    return mxy_hash_bytes(s ? s : \"\", (size_t)mxy_str_len(s));\n" "}\n" "MXY_FN int mxy_cmp_str(const void *a, const void *b) { return mxy_str_cmp(*(const mxy_str *)a, *(const mxy_str *)b); }\n" "MXY_FN void mxy_fmtp_str(mxy_buf *b, const void *p, int nested) {\n" "    mxy_str s = *(const mxy_str *)p;\n" "    if (nested && s) mxy_fmt_quoted(b, s, mxy_str_len(s), '\"');\n" "    else mxy_fmtv_str(b, s);\n" "}\n" "static const mxy_vw mxy_vw_str __attribute__((unused)) = {sizeof(mxy_str), mxy_copy_str, mxy_drop_str, mxy_eq_str, mxy_hash_str, mxy_cmp_str, mxy_fmtp_str, \"string\"};\n" "\n" "MXY_FN mxy_str mxy_str_of(const mxy_vw *vw, const void *p) {\n" "    mxy_buf b = {0};\n" "    mxy_vw_fmt(vw, &b, p, 0);\n" "    return mxy_str_from_buf(&b);\n" "}\n" "/* moxy runtime: lists (copy-on-write, reference counted; NULL is the empty list) */\n" "typedef struct mxy_list {\n" "    int64_t rc;\n" "    int64_t len;\n" "    int64_t cap;\n" "    const mxy_vw *vw;\n" "    char *data;\n" "} mxy_list;\n" "\n" "#define MXY_AT(l, i) ((l)->data + (size_t)(i) * (l)->vw->size)\n" "\n" "MXY_FN mxy_list *mxy_list_new(const mxy_vw *vw, int64_t cap) {\n" "    mxy_list *l = (mxy_list *)mxy_alloc(sizeof(mxy_list));\n" "    l->rc = 1;\n" "    l->len = 0;\n" "    l->cap = cap < 4 ? 4 : cap;\n" "    l->vw = vw;\n" "    l->data = (char *)mxy_alloc((size_t)l->cap * vw->size);\n" "    return l;\n" "}\n" "\n" "MXY_INLINE mxy_list *mxy_list_retain(mxy_list *l) {\n" "    if (l) mxy_rc_inc(&l->rc);\n" "    return l;\n" "}\n" "\n" "MXY_FN void mxy_list_release(mxy_list *l) {\n" "    if (!l || !mxy_rc_dec(&l->rc)) return;\n" "    if (l->vw->drop)\n" "        for (int64_t i = 0; i < l->len; i++) l->vw->drop(MXY_AT(l, i));\n" "    free(l->data);\n" "    free(l);\n" "}\n" "\n" "MXY_INLINE int64_t mxy_list_len(const mxy_list *l) { return l ? l->len : 0; }\n" "\n" "/* takes ownership of n elements at `elems` */\n" "MXY_FN mxy_list *mxy_list_from(const mxy_vw *vw, int64_t n, const void *elems) {\n" "    mxy_list *l = mxy_list_new(vw, n);\n" "    if (n) memcpy(l->data, elems, (size_t)n * vw->size);\n" "    l->len = n;\n" "    return l;\n" "}\n" "\n" "MXY_FN mxy_list *mxy_list_clone(const mxy_list *src, const mxy_vw *vw, int64_t cap) {\n" "    mxy_list *l = mxy_list_new(vw, cap);\n" "    int64_t n = mxy_list_len(src);\n" "    for (int64_t i = 0; i < n; i++) mxy_vw_copy(vw, MXY_AT(l, i), MXY_AT(src, i));\n" "    l->len = n;\n" "    return l;\n" "}\n" "\n" "/* make *lp uniquely owned before mutation */\n" "MXY_FN void mxy_list_unique(mxy_list **lp, const mxy_vw *vw) {\n" "    mxy_list *l = *lp;\n" "    if (!l) {\n" "        *lp = mxy_list_new(vw, 4);\n" "        return;\n" "    }\n" "    if (l->rc == 1 || l->rc < 0) return;\n" "    mxy_list *c = mxy_list_clone(l, l->vw, l->cap);\n" "    mxy_list_release(l);\n" "    *lp = c;\n" "}\n" "\n" "MXY_FN void mxy_list_reserve(mxy_list *l, int64_t n) {\n" "    if (n <= l->cap) return;\n" "    int64_t cap = l->cap * 2;\n" "    if (cap < n) cap = n;\n" "    l->data = (char *)mxy_realloc(l->data, (size_t)cap * l->vw->size);\n" "    l->cap = cap;\n" "}\n" "\n" "MXY_FN void mxy_list_push(mxy_list **lp, const mxy_vw *vw, const void *elem, int move) {\n" "    mxy_list_unique(lp, vw);\n" "    mxy_list *l = *lp;\n" "    mxy_list_reserve(l, l->len + 1);\n" "    if (move) memcpy(MXY_AT(l, l->len), elem, vw->size);\n" "    else mxy_vw_copy(vw, MXY_AT(l, l->len), elem);\n" "    l->len++;\n" "}\n" "\n" "MXY_FN MXY_NORETURN void mxy_list_oob(int64_t i, int64_t n, const char *loc) {\n" "    mxy_panic(loc, \"index %lld out of range for list of length %lld\", (long long)i, (long long)n);\n" "}\n" "\n" "MXY_INLINE void *mxy_list_at(const mxy_list *l, int64_t i, const char *loc) {\n" "    int64_t n = mxy_list_len(l);\n" "    if (i < 0 || i >= n) mxy_list_oob(i, n, loc);\n" "    return MXY_AT(l, i);\n" "}\n" "\n" "MXY_FN void *mxy_list_at_mut(mxy_list **lp, const mxy_vw *vw, int64_t i, const char *loc) {\n" "    int64_t n = mxy_list_len(*lp);\n" "    if (i < 0 || i >= n) mxy_list_oob(i, n, loc);\n" "    mxy_list_unique(lp, vw);\n" "    return MXY_AT(*lp, i);\n" "}\n" "\n" "MXY_FN void mxy_list_set(mxy_list **lp, const mxy_vw *vw, int64_t i, const void *val, int move, const char *loc) {\n" "    void *slot = mxy_list_at_mut(lp, vw, i, loc);\n" "    char old[vw->size > 0 ? vw->size : 1];\n" "    memcpy(old, slot, vw->size);\n" "    if (move) memcpy(slot, val, vw->size);\n" "    else mxy_vw_copy(vw, slot, val);\n" "    mxy_vw_drop(vw, old);\n" "}\n" "\n" "MXY_FN void mxy_list_pop(mxy_list **lp, const mxy_vw *vw, void *out, const char *loc) {\n" "    if (!mxy_list_len(*lp)) mxy_panic(loc, \"pop from an empty list\");\n" "    mxy_list_unique(lp, vw);\n" "    mxy_list *l = *lp;\n" "    l->len--;\n" "    memcpy(out, MXY_AT(l, l->len), vw->size);\n" "}\n" "\n" "MXY_FN void mxy_list_insert(mxy_list **lp, const mxy_vw *vw, int64_t i, const void *val, int move, const char *loc) {\n" "    int64_t n = mxy_list_len(*lp);\n" "    if (i < 0 || i > n) mxy_list_oob(i, n, loc);\n" "    mxy_list_unique(lp, vw);\n" "    mxy_list *l = *lp;\n" "    mxy_list_reserve(l, l->len + 1);\n" "    memmove(MXY_AT(l, i + 1), MXY_AT(l, i), (size_t)(l->len - i) * vw->size);\n" "    if (move) memcpy(MXY_AT(l, i), val, vw->size);\n" "    else mxy_vw_copy(vw, MXY_AT(l, i), val);\n" "    l->len++;\n" "}\n" "\n" "MXY_FN void mxy_list_remove(mxy_list **lp, const mxy_vw *vw, int64_t i, void *out, const char *loc) {\n" "    int64_t n = mxy_list_len(*lp);\n" "    if (i < 0 || i >= n) mxy_list_oob(i, n, loc);\n" "    mxy_list_unique(lp, vw);\n" "    mxy_list *l = *lp;\n" "    memcpy(out, MXY_AT(l, i), vw->size);\n" "    memmove(MXY_AT(l, i), MXY_AT(l, i + 1), (size_t)(l->len - i - 1) * vw->size);\n" "    l->len--;\n" "}\n" "\n" "MXY_FN void mxy_list_clear(mxy_list **lp) {\n" "    mxy_list_release(*lp);\n" "    *lp = NULL;\n" "}\n" "\n" "MXY_FN int64_t mxy_list_index_of(const mxy_list *l, const mxy_vw *vw, const void *x) {\n" "    for (int64_t i = 0; i < mxy_list_len(l); i++)\n" "        if (mxy_vw_eq(vw, MXY_AT(l, i), x)) return i;\n" "    return -1;\n" "}\n" "\n" "MXY_FN mxy_list *mxy_list_slice(const mxy_list *l, const mxy_vw *vw, int64_t a, int64_t b, const char *loc) {\n" "    int64_t n = mxy_list_len(l);\n" "    if (a < 0 || b < a || b > n)\n" "        mxy_panic(loc, \"slice [%lld, %lld) out of range for list of length %lld\", (long long)a, (long long)b, (long long)n);\n" "    mxy_list *r = mxy_list_new(vw, b - a);\n" "    for (int64_t i = a; i < b; i++) mxy_vw_copy(vw, MXY_AT(r, i - a), MXY_AT(l, i));\n" "    r->len = b - a;\n" "    return r;\n" "}\n" "\n" "MXY_FN mxy_list *mxy_list_concat(const mxy_list *a, const mxy_list *b, const mxy_vw *vw) {\n" "    mxy_list *r = mxy_list_clone(a, vw, mxy_list_len(a) + mxy_list_len(b));\n" "    for (int64_t i = 0; i < mxy_list_len(b); i++) mxy_vw_copy(vw, MXY_AT(r, r->len++), MXY_AT(b, i));\n" "    return r;\n" "}\n" "\n" "MXY_FN void mxy_list_reverse(mxy_list **lp, const mxy_vw *vw) {\n" "    if (mxy_list_len(*lp) < 2) return;\n" "    mxy_list_unique(lp, vw);\n" "    mxy_list *l = *lp;\n" "    char tmp[vw->size];\n" "    for (int64_t i = 0, j = l->len - 1; i < j; i++, j--) {\n" "        memcpy(tmp, MXY_AT(l, i), vw->size);\n" "        memcpy(MXY_AT(l, i), MXY_AT(l, j), vw->size);\n" "        memcpy(MXY_AT(l, j), tmp, vw->size);\n" "    }\n" "}\n" "\n" "MXY_FN void mxy_merge_sort(char *a, char *tmp, int64_t n, const mxy_vw *vw) {\n" "    if (n < 2) return;\n" "    int64_t mid = n / 2;\n" "    size_t sz = vw->size;\n" "    mxy_merge_sort(a, tmp, mid, vw);\n" "    mxy_merge_sort(a + (size_t)mid * sz, tmp, n - mid, vw);\n" "    int64_t i = 0, j = mid, k = 0;\n" "    while (i < mid && j < n) {\n" "        if (vw->cmp(a + (size_t)j * sz, a + (size_t)i * sz) < 0) memcpy(tmp + (size_t)k++ * sz, a + (size_t)j++ * sz, sz);\n" "        else memcpy(tmp + (size_t)k++ * sz, a + (size_t)i++ * sz, sz);\n" "    }\n" "    while (i < mid) memcpy(tmp + (size_t)k++ * sz, a + (size_t)i++ * sz, sz);\n" "    while (j < n) memcpy(tmp + (size_t)k++ * sz, a + (size_t)j++ * sz, sz);\n" "    memcpy(a, tmp, (size_t)n * sz);\n" "}\n" "\n" "MXY_FN void mxy_list_sort(mxy_list **lp, const mxy_vw *vw) {\n" "    if (mxy_list_len(*lp) < 2) return;\n" "    if (!vw->cmp) mxy_panic(NULL, \"values of type %s cannot be sorted\", vw->name);\n" "    mxy_list_unique(lp, vw);\n" "    mxy_list *l = *lp;\n" "    char *tmp = (char *)mxy_alloc((size_t)l->len * vw->size);\n" "    mxy_merge_sort(l->data, tmp, l->len, vw);\n" "    free(tmp);\n" "}\n" "\n" "MXY_FN bool mxy_list_eq(const mxy_list *a, const mxy_list *b) {\n" "    int64_t n = mxy_list_len(a);\n" "    if (n != mxy_list_len(b)) return false;\n" "    for (int64_t i = 0; i < n; i++)\n" "        if (!mxy_vw_eq(a->vw, MXY_AT(a, i), MXY_AT(b, i))) return false;\n" "    return true;\n" "}\n" "\n" "MXY_FN void mxy_list_fmt(mxy_buf *b, const mxy_list *l) {\n" "    mxy_buf_putc(b, '[');\n" "    for (int64_t i = 0; i < mxy_list_len(l); i++) {\n" "        if (i) mxy_buf_puts(b, \", \");\n" "        mxy_vw_fmt(l->vw, b, MXY_AT(l, i), 1);\n" "    }\n" "    mxy_buf_putc(b, ']');\n" "}\n" "\n" "MXY_FN mxy_str mxy_list_join(const mxy_list *l, mxy_str sep) {\n" "    mxy_buf b = {0};\n" "    for (int64_t i = 0; i < mxy_list_len(l); i++) {\n" "        if (i && sep) mxy_buf_put(&b, sep, mxy_str_len(sep));\n" "        mxy_vw_fmt(l->vw, &b, MXY_AT(l, i), 0);\n" "    }\n" "    return mxy_str_from_buf(&b);\n" "}\n" "\n" "MXY_FN void mxy_copy_list(void *dst, const void *src) { *(mxy_list **)dst = mxy_list_retain(*(mxy_list *const *)src); }\n" "MXY_FN void mxy_drop_list(void *p) { mxy_list_release(*(mxy_list **)p); }\n" "MXY_FN bool mxy_eq_list(const void *a, const void *b) { return mxy_list_eq(*(mxy_list *const *)a, *(mxy_list *const *)b); }\n" "MXY_FN uint64_t mxy_hash_list(const void *p) {\n" "    const mxy_list *l = *(mxy_list *const *)p;\n" "    uint64_t h = 7;\n" "    for (int64_t i = 0; i < mxy_list_len(l); i++) h = h * 31 + mxy_vw_hash(l->vw, MXY_AT(l, i));\n" "    return h;\n" "}\n" "MXY_FN void mxy_fmtp_list(mxy_buf *b, const void *p, int nested) {\n" "    (void)nested;\n" "    mxy_list_fmt(b, *(mxy_list *const *)p);\n" "}\n" "static const mxy_vw mxy_vw_list __attribute__((unused)) = {sizeof(mxy_list *), mxy_copy_list, mxy_drop_list, mxy_eq_list, mxy_hash_list, NULL, mxy_fmtp_list, \"list\"};\n" "\n" "MXY_FN mxy_list *mxy_str_split(mxy_str s, mxy_str sep) {\n" "    mxy_list *out = mxy_list_new(&mxy_vw_str, 4);\n" "    int64_t n = mxy_str_len(s), m = mxy_str_len(sep);\n" "    int64_t start = 0;\n" "    if (m == 0) {\n" "        for (int64_t i = 0; i < n; i++) {\n" "            mxy_str c = mxy_str_fromn(s + i, 1);\n" "            mxy_list_push(&out, &mxy_vw_str, &c, 1);\n" "        }\n" "        return out;\n" "    }\n" "    for (int64_t i = 0; i + m <= n;) {\n" "        if (memcmp(s + i, sep, (size_t)m) == 0) {\n" "            mxy_str part = mxy_str_fromn(s + start, i - start);\n" "            mxy_list_push(&out, &mxy_vw_str, &part, 1);\n" "            i += m;\n" "            start = i;\n" "        } else {\n" "            i++;\n" "        }\n" "    }\n" "    mxy_str last = mxy_str_fromn(s ? s + start : \"\", n - start);\n" "    mxy_list_push(&out, &mxy_vw_str, &last, 1);\n" "    return out;\n" "}\n" "\n" "MXY_FN mxy_list *mxy_str_lines(mxy_str s) {\n" "    mxy_list *out = mxy_list_new(&mxy_vw_str, 4);\n" "    int64_t n = mxy_str_len(s), start = 0;\n" "    for (int64_t i = 0; i < n; i++) {\n" "        if (s[i] != '\\n') continue;\n" "        int64_t end = i > start && s[i - 1] == '\\r' ? i - 1 : i;\n" "        mxy_str part = mxy_str_fromn(s + start, end - start);\n" "        mxy_list_push(&out, &mxy_vw_str, &part, 1);\n" "        start = i + 1;\n" "    }\n" "    if (start < n) {\n" "        mxy_str part = mxy_str_fromn(s + start, n - start);\n" "        mxy_list_push(&out, &mxy_vw_str, &part, 1);\n" "    }\n" "    return out;\n" "}\n" "\n" "MXY_FN mxy_list *mxy_str_chars(mxy_str s) {\n" "    int64_t n = mxy_str_len(s);\n" "    return mxy_list_from(&mxy_vw_char, n, s ? s : \"\");\n" "}\n" "/* moxy runtime: maps (insertion-ordered hash maps, copy-on-write; NULL is empty) */\n" "typedef struct {\n" "    uint64_t hash;\n" "    int64_t live;\n" "} mxy_entry;\n" "\n" "typedef struct mxy_map {\n" "    int64_t rc;\n" "    int64_t len;    /* live entries */\n" "    int64_t count;  /* used entry slots (live + removed) */\n" "    int64_t cap;    /* entry slots */\n" "    const mxy_vw *kvw;\n" "    const mxy_vw *vvw;\n" "    size_t koff;\n" "    size_t voff;\n" "    size_t esize;\n" "    char *entries;\n" "    int64_t *index; /* -1 empty, -2 removed, otherwise entry slot */\n" "    int64_t icap;\n" "} mxy_map;\n" "\n" "#define MXY_ALIGN8(n) (((n) + 7) & ~(size_t)7)\n" "#define MXY_ENTRY(m, i) ((mxy_entry *)((m)->entries + (size_t)(i) * (m)->esize))\n" "#define MXY_KEY(m, i) ((void *)((m)->entries + (size_t)(i) * (m)->esize + (m)->koff))\n" "#define MXY_VAL(m, i) ((void *)((m)->entries + (size_t)(i) * (m)->esize + (m)->voff))\n" "\n" "MXY_FN mxy_map *mxy_map_new(const mxy_vw *kvw, const mxy_vw *vvw, int64_t cap) {\n" "    mxy_map *m = (mxy_map *)mxy_zalloc(sizeof(mxy_map));\n" "    m->rc = 1;\n" "    m->kvw = kvw;\n" "    m->vvw = vvw;\n" "    m->koff = sizeof(mxy_entry);\n" "    m->voff = m->koff + MXY_ALIGN8(kvw->size);\n" "    m->esize = m->voff + MXY_ALIGN8(vvw->size);\n" "    m->cap = cap < 8 ? 8 : cap;\n" "    m->entries = (char *)mxy_alloc((size_t)m->cap * m->esize);\n" "    m->icap = 16;\n" "    while (m->icap < m->cap * 2) m->icap *= 2;\n" "    m->index = (int64_t *)mxy_alloc((size_t)m->icap * sizeof(int64_t));\n" "    for (int64_t i = 0; i < m->icap; i++) m->index[i] = -1;\n" "    return m;\n" "}\n" "\n" "MXY_INLINE mxy_map *mxy_map_retain(mxy_map *m) {\n" "    if (m) mxy_rc_inc(&m->rc);\n" "    return m;\n" "}\n" "\n" "MXY_FN void mxy_map_release(mxy_map *m) {\n" "    if (!m || !mxy_rc_dec(&m->rc)) return;\n" "    for (int64_t i = 0; i < m->count; i++) {\n" "        if (!MXY_ENTRY(m, i)->live) continue;\n" "        mxy_vw_drop(m->kvw, MXY_KEY(m, i));\n" "        mxy_vw_drop(m->vvw, MXY_VAL(m, i));\n" "    }\n" "    free(m->entries);\n" "    free(m->index);\n" "    free(m);\n" "}\n" "\n" "MXY_INLINE int64_t mxy_map_len(const mxy_map *m) { return m ? m->len : 0; }\n" "\n" "MXY_FN int64_t mxy_map_find(const mxy_map *m, const void *key, uint64_t h) {\n" "    if (!m) return -1;\n" "    int64_t mask = m->icap - 1;\n" "    for (int64_t i = (int64_t)(h & (uint64_t)mask);; i = (i + 1) & mask) {\n" "        int64_t slot = m->index[i];\n" "        if (slot == -1) return -1;\n" "        if (slot >= 0 && MXY_ENTRY(m, slot)->hash == h && mxy_vw_eq(m->kvw, MXY_KEY(m, slot), key)) return slot;\n" "    }\n" "}\n" "\n" "MXY_FN void mxy_map_reindex(mxy_map *m, int64_t icap) {\n" "    free(m->index);\n" "    m->icap = icap;\n" "    m->index = (int64_t *)mxy_alloc((size_t)icap * sizeof(int64_t));\n" "    for (int64_t i = 0; i < icap; i++) m->index[i] = -1;\n" "    for (int64_t s = 0; s < m->count; s++) {\n" "        if (!MXY_ENTRY(m, s)->live) continue;\n" "        int64_t i = (int64_t)(MXY_ENTRY(m, s)->hash & (uint64_t)(icap - 1));\n" "        while (m->index[i] != -1) i = (i + 1) & (icap - 1);\n" "        m->index[i] = s;\n" "    }\n" "}\n" "\n" "/* drop removed slots and grow so one more entry fits */\n" "MXY_FN void mxy_map_grow(mxy_map *m) {\n" "    if (m->count < m->cap) return;\n" "    int64_t w = 0;\n" "    for (int64_t s = 0; s < m->count; s++) {\n" "        if (!MXY_ENTRY(m, s)->live) continue;\n" "        if (w != s) memcpy(m->entries + (size_t)w * m->esize, m->entries + (size_t)s * m->esize, m->esize);\n" "        w++;\n" "    }\n" "    m->count = w;\n" "    if (m->count * 2 >= m->cap) {\n" "        m->cap *= 2;\n" "        m->entries = (char *)mxy_realloc(m->entries, (size_t)m->cap * m->esize);\n" "    }\n" "    int64_t icap = m->icap;\n" "    while (icap < m->cap * 2) icap *= 2;\n" "    mxy_map_reindex(m, icap);\n" "}\n" "\n" "MXY_FN mxy_map *mxy_map_clone(const mxy_map *src) {\n" "    mxy_map *m = mxy_map_new(src->kvw, src->vvw, src->len);\n" "    for (int64_t s = 0; s < src->count; s++) {\n" "        if (!MXY_ENTRY(src, s)->live) continue;\n" "        int64_t d = m->count++;\n" "        *MXY_ENTRY(m, d) = *MXY_ENTRY(src, s);\n" "        mxy_vw_copy(m->kvw, MXY_KEY(m, d), MXY_KEY(src, s));\n" "        mxy_vw_copy(m->vvw, MXY_VAL(m, d), MXY_VAL(src, s));\n" "        m->len++;\n" "    }\n" "    mxy_map_reindex(m, m->icap);\n" "    return m;\n" "}\n" "\n" "MXY_FN void mxy_map_unique(mxy_map **mp, const mxy_vw *kvw, const mxy_vw *vvw) {\n" "    if (!*mp) {\n" "        *mp = mxy_map_new(kvw, vvw, 8);\n" "        return;\n" "    }\n" "    if (mxy_rc_load(&(*mp)->rc) == 1) return;\n" "    mxy_map *c = mxy_map_clone(*mp);\n" "    mxy_map_release(*mp);\n" "    *mp = c;\n" "}\n" "\n" "MXY_FN void mxy_map_set(mxy_map **mp, const mxy_vw *kvw, const mxy_vw *vvw, const void *key, const void *val,\n" "                        int kmove, int vmove) {\n" "    mxy_map_unique(mp, kvw, vvw);\n" "    mxy_map *m = *mp;\n" "    uint64_t h = mxy_vw_hash(kvw, key);\n" "    int64_t slot = mxy_map_find(m, key, h);\n" "    if (slot >= 0) {\n" "        if (kmove) mxy_vw_drop(kvw, (void *)key);\n" "        mxy_vw_drop(vvw, MXY_VAL(m, slot));\n" "        if (vmove) memcpy(MXY_VAL(m, slot), val, vvw->size);\n" "        else mxy_vw_copy(vvw, MXY_VAL(m, slot), val);\n" "        return;\n" "    }\n" "    mxy_map_grow(m);\n" "    slot = m->count++;\n" "    MXY_ENTRY(m, slot)->hash = h;\n" "    MXY_ENTRY(m, slot)->live = 1;\n" "    if (kmove) memcpy(MXY_KEY(m, slot), key, kvw->size);\n" "    else mxy_vw_copy(kvw, MXY_KEY(m, slot), key);\n" "    if (vmove) memcpy(MXY_VAL(m, slot), val, vvw->size);\n" "    else mxy_vw_copy(vvw, MXY_VAL(m, slot), val);\n" "    m->len++;\n" "    int64_t i = (int64_t)(h & (uint64_t)(m->icap - 1));\n" "    while (m->index[i] >= 0) i = (i + 1) & (m->icap - 1);\n" "    m->index[i] = slot;\n" "}\n" "\n" "MXY_FN void *mxy_map_get(const mxy_map *m, const mxy_vw *kvw, const void *key, const char *loc) {\n" "    int64_t slot = mxy_map_find(m, key, mxy_vw_hash(kvw, key));\n" "    if (slot < 0) {\n" "        mxy_buf b = {0};\n" "        mxy_vw_fmt(kvw, &b, key, 1);\n" "        mxy_panic(loc, \"key %s not found in map\", b.data ? b.data : \"\");\n" "    }\n" "    return MXY_VAL(m, slot);\n" "}\n" "\n" "MXY_FN void *mxy_map_lookup(const mxy_map *m, const mxy_vw *kvw, const void *key) {\n" "    int64_t slot = mxy_map_find(m, key, mxy_vw_hash(kvw, key));\n" "    return slot < 0 ? NULL : MXY_VAL(m, slot);\n" "}\n" "\n" "MXY_FN bool mxy_map_has(const mxy_map *m, const mxy_vw *kvw, const void *key) {\n" "    return mxy_map_find(m, key, mxy_vw_hash(kvw, key)) >= 0;\n" "}\n" "\n" "MXY_FN bool mxy_map_remove(mxy_map **mp, const mxy_vw *kvw, const mxy_vw *vvw, const void *key) {\n" "    if (!*mp || !mxy_map_has(*mp, kvw, key)) return false;\n" "    mxy_map_unique(mp, kvw, vvw);\n" "    mxy_map *m = *mp;\n" "    uint64_t h = mxy_vw_hash(kvw, key);\n" "    int64_t mask = m->icap - 1;\n" "    for (int64_t i = (int64_t)(h & (uint64_t)mask);; i = (i + 1) & mask) {\n" "        int64_t slot = m->index[i];\n" "        if (slot == -1) return false;\n" "        if (slot >= 0 && MXY_ENTRY(m, slot)->hash == h && mxy_vw_eq(kvw, MXY_KEY(m, slot), key)) {\n" "            mxy_vw_drop(kvw, MXY_KEY(m, slot));\n" "            mxy_vw_drop(vvw, MXY_VAL(m, slot));\n" "            MXY_ENTRY(m, slot)->live = 0;\n" "            m->index[i] = -2;\n" "            m->len--;\n" "            return true;\n" "        }\n" "    }\n" "}\n" "\n" "MXY_FN void mxy_map_clear(mxy_map **mp) {\n" "    mxy_map_release(*mp);\n" "    *mp = NULL;\n" "}\n" "\n" "MXY_FN mxy_list *mxy_map_keys(const mxy_map *m, const mxy_vw *kvw) {\n" "    mxy_list *l = mxy_list_new(kvw, mxy_map_len(m));\n" "    for (int64_t s = 0; m && s < m->count; s++)\n" "        if (MXY_ENTRY(m, s)->live) mxy_list_push(&l, kvw, MXY_KEY(m, s), 0);\n" "    return l;\n" "}\n" "\n" "MXY_FN mxy_list *mxy_map_values(const mxy_map *m, const mxy_vw *vvw) {\n" "    mxy_list *l = mxy_list_new(vvw, mxy_map_len(m));\n" "    for (int64_t s = 0; m && s < m->count; s++)\n" "        if (MXY_ENTRY(m, s)->live) mxy_list_push(&l, vvw, MXY_VAL(m, s), 0);\n" "    return l;\n" "}\n" "\n" "MXY_INLINE int64_t mxy_map_slots(const mxy_map *m) { return m ? m->count : 0; }\n" "MXY_INLINE bool mxy_map_live(const mxy_map *m, int64_t s) { return MXY_ENTRY(m, s)->live != 0; }\n" "\n" "MXY_FN bool mxy_map_eq(const mxy_map *a, const mxy_map *b) {\n" "    if (mxy_map_len(a) != mxy_map_len(b)) return false;\n" "    for (int64_t s = 0; a && s < a->count; s++) {\n" "        if (!MXY_ENTRY(a, s)->live) continue;\n" "        void *v = mxy_map_lookup(b, a->kvw, MXY_KEY(a, s));\n" "        if (!v || !mxy_vw_eq(a->vvw, MXY_VAL(a, s), v)) return false;\n" "    }\n" "    return true;\n" "}\n" "\n" "MXY_FN void mxy_map_fmt(mxy_buf *b, const mxy_map *m) {\n" "    mxy_buf_putc(b, '{');\n" "    int first = 1;\n" "    for (int64_t s = 0; m && s < m->count; s++) {\n" "        if (!MXY_ENTRY(m, s)->live) continue;\n" "        if (!first) mxy_buf_puts(b, \", \");\n" "        first = 0;\n" "        mxy_vw_fmt(m->kvw, b, MXY_KEY(m, s), 1);\n" "        mxy_buf_puts(b, \": \");\n" "        mxy_vw_fmt(m->vvw, b, MXY_VAL(m, s), 1);\n" "    }\n" "    mxy_buf_putc(b, '}');\n" "}\n" "\n" "MXY_FN void mxy_copy_map(void *dst, const void *src) { *(mxy_map **)dst = mxy_map_retain(*(mxy_map *const *)src); }\n" "MXY_FN void mxy_drop_map(void *p) { mxy_map_release(*(mxy_map **)p); }\n" "MXY_FN bool mxy_eq_map(const void *a, const void *b) { return mxy_map_eq(*(mxy_map *const *)a, *(mxy_map *const *)b); }\n" "MXY_FN void mxy_fmtp_map(mxy_buf *b, const void *p, int nested) {\n" "    (void)nested;\n" "    mxy_map_fmt(b, *(mxy_map *const *)p);\n" "}\n" "static const mxy_vw mxy_vw_map __attribute__((unused)) = {sizeof(mxy_map *), mxy_copy_map, mxy_drop_map, mxy_eq_map, NULL, NULL, mxy_fmtp_map, \"map\"};\n" "\n" "MXY_FN void *mxy_map_get_mut(mxy_map **mp, const mxy_vw *kvw, const mxy_vw *vvw, const void *key, const char *loc) {\n" "    if (!mxy_map_has(*mp, kvw, key)) mxy_map_get(*mp, kvw, key, loc);\n" "    mxy_map_unique(mp, kvw, vvw);\n" "    return mxy_map_get(*mp, kvw, key, loc);\n" "}\n" "/* moxy runtime: ref objects (shared, reference counted, with weak references)\n" "   strong counts live references; weak counts weak references plus one held\n" "   collectively by all strong references. Fields are dropped when the last\n" "   strong reference goes; memory is freed when the last weak one goes. */\n" "typedef struct mxy_obj {\n" "    int64_t strong;\n" "    int64_t weak;\n" "    void (*drop)(void *self);\n" "    void (*fmt)(mxy_buf *b, const void *self);\n" "    const char *name;\n" "} mxy_obj;\n" "\n" "MXY_FN void *mxy_obj_new(size_t size, void (*drop)(void *), void (*fmt)(mxy_buf *, const void *), const char *name) {\n" "    mxy_obj *o = (mxy_obj *)mxy_zalloc(size);\n" "    o->strong = 1;\n" "    o->weak = 1;\n" "    o->drop = drop;\n" "    o->fmt = fmt;\n" "    o->name = name;\n" "    return o;\n" "}\n" "\n" "MXY_INLINE void *mxy_obj_retain(void *p) {\n" "    if (p) mxy_rc_inc(&((mxy_obj *)p)->strong);\n" "    return p;\n" "}\n" "\n" "MXY_INLINE void *mxy_obj_weak_retain(void *p) {\n" "    if (p) mxy_rc_inc(&((mxy_obj *)p)->weak);\n" "    return p;\n" "}\n" "\n" "MXY_FN void mxy_obj_weak_release(void *p) {\n" "    if (p && mxy_rc_dec(&((mxy_obj *)p)->weak)) free(p);\n" "}\n" "\n" "MXY_FN void mxy_obj_release(void *p) {\n" "    mxy_obj *o = (mxy_obj *)p;\n" "    if (!o || !mxy_rc_dec(&o->strong)) return;\n" "    if (o->drop) o->drop(o);\n" "    mxy_obj_weak_release(o);\n" "}\n" "\n" "/* strong reference from a weak one, or NULL once the object is gone */\n" "MXY_FN void *mxy_obj_weak_load(void *p) {\n" "    mxy_obj *o = (mxy_obj *)p;\n" "    if (!o) return NULL;\n" "    int64_t s = __atomic_load_n(&o->strong, __ATOMIC_ACQUIRE);\n" "    while (s > 0)\n" "        if (__atomic_compare_exchange_n(&o->strong, &s, s + 1, 1, __ATOMIC_ACQ_REL, __ATOMIC_ACQUIRE)) return o;\n" "    return NULL;\n" "}\n" "\n" "MXY_FN void mxy_copy_obj(void *dst, const void *src) { *(void **)dst = mxy_obj_retain(*(void *const *)src); }\n" "MXY_FN void mxy_drop_obj(void *p) { mxy_obj_release(*(void **)p); }\n" "MXY_FN void mxy_fmtp_obj(mxy_buf *b, const void *p, int nested) {\n" "    (void)nested;\n" "    const mxy_obj *o = *(mxy_obj *const *)p;\n" "    if (!o) mxy_buf_puts(b, \"null\");\n" "    else if (o->fmt) o->fmt(b, o);\n" "    else mxy_buf_printf(b, \"%s@%p\", o->name ? o->name : \"object\", (const void *)o);\n" "}\n" "static const mxy_vw mxy_vw_obj __attribute__((unused)) = {sizeof(void *), mxy_copy_obj, mxy_drop_obj, mxy_eq_ptr, mxy_hash_ptr, mxy_cmp_ptr, mxy_fmtp_obj, \"ref\"};\n" "/* moxy runtime: closures. Captured values live after the header; `fn` takes\n" "   the closure itself as its first argument. */\n" "typedef struct mxy_fn {\n" "    int64_t rc;\n" "    void *fn;\n" "    void (*drop)(struct mxy_fn *self);\n" "} mxy_fn;\n" "\n" "MXY_INLINE mxy_fn *mxy_fn_retain(mxy_fn *f) {\n" "    if (f) mxy_rc_inc(&f->rc);\n" "    return f;\n" "}\n" "\n" "MXY_FN void mxy_fn_release(mxy_fn *f) {\n" "    if (!f || !mxy_rc_dec(&f->rc)) return;\n" "    if (f->drop) f->drop(f);\n" "    free(f);\n" "}\n" "\n" "MXY_FN MXY_NORETURN void mxy_fn_null(const char *loc) { mxy_panic(loc, \"call of a null closure\"); }\n" "\n" "MXY_INLINE mxy_fn *mxy_fn_check(mxy_fn *f, const char *loc) {\n" "    if (!f) mxy_fn_null(loc);\n" "    return f;\n" "}\n" "\n" "MXY_FN void mxy_copy_fn(void *dst, const void *src) { *(mxy_fn **)dst = mxy_fn_retain(*(mxy_fn *const *)src); }\n" "MXY_FN void mxy_drop_fn(void *p) { mxy_fn_release(*(mxy_fn **)p); }\n" "MXY_FN void mxy_fmtp_fn(mxy_buf *b, const void *p, int nested) {\n" "    (void)p;\n" "    (void)nested;\n" "    mxy_buf_puts(b, \"<fn>\");\n" "}\n" "static const mxy_vw mxy_vw_fn __attribute__((unused)) = {sizeof(mxy_fn *), mxy_copy_fn, mxy_drop_fn, mxy_eq_ptr, mxy_hash_ptr, NULL, mxy_fmtp_fn, \"fn\"};\n" "/* moxy runtime: futures (one thread per async call). The thread owns its\n" "   arguments; handles are reference counted. The last handle joins a finished\n" "   thread or detaches a running one, which then frees the future itself. */\n" "#ifdef MXY_THREADS\n" "typedef struct mxy_future {\n" "    int64_t rc;\n" "    pthread_t thread;\n" "    pthread_mutex_t lock;\n" "    pthread_cond_t cond;\n" "    int done;\n" "    int orphaned;\n" "    const mxy_vw *vw;\n" "    void *args;\n" "    void (*run)(void *args, void *out);\n" "    void (*drop_args)(void *args);\n" "    char *result;\n" "} mxy_future;\n" "\n" "MXY_FN void mxy_future_free(mxy_future *f) {\n" "    if (f->vw->size) mxy_vw_drop(f->vw, f->result);\n" "    pthread_mutex_destroy(&f->lock);\n" "    pthread_cond_destroy(&f->cond);\n" "    free(f->result);\n" "    free(f);\n" "}\n" "\n" "MXY_FN void *mxy_future_main(void *p) {\n" "    mxy_future *f = (mxy_future *)p;\n" "    f->run(f->args, f->result);\n" "    if (f->drop_args) f->drop_args(f->args);\n" "    free(f->args);\n" "    f->args = NULL;\n" "    pthread_mutex_lock(&f->lock);\n" "    f->done = 1;\n" "    int orphaned = f->orphaned;\n" "    pthread_cond_broadcast(&f->cond);\n" "    pthread_mutex_unlock(&f->lock);\n" "    if (orphaned) mxy_future_free(f);\n" "    return NULL;\n" "}\n" "\n" "MXY_FN mxy_future *mxy_future_spawn(const mxy_vw *vw, void *args, void (*run)(void *, void *),\n" "                                    void (*drop_args)(void *)) {\n" "    mxy_future *f = (mxy_future *)mxy_zalloc(sizeof(mxy_future));\n" "    f->rc = 1;\n" "    f->vw = vw;\n" "    f->args = args;\n" "    f->run = run;\n" "    f->drop_args = drop_args;\n" "    f->result = (char *)mxy_zalloc(vw->size ? vw->size : 1);\n" "    pthread_mutex_init(&f->lock, NULL);\n" "    pthread_cond_init(&f->cond, NULL);\n" "    if (pthread_create(&f->thread, NULL, mxy_future_main, f) != 0) {\n" "        /* no thread available: run inline so the program still makes progress */\n" "        f->orphaned = 0;\n" "        mxy_future_main(f);\n" "        f->thread = pthread_self();\n" "        f->done = 2;\n" "    }\n" "    return f;\n" "}\n" "\n" "/* waits for completion; returns a borrowed pointer to the result */\n" "MXY_FN void *mxy_future_await(mxy_future *f, const char *loc) {\n" "    if (!f) mxy_panic(loc, \"await on a null future\");\n" "    pthread_mutex_lock(&f->lock);\n" "    while (!f->done) pthread_cond_wait(&f->cond, &f->lock);\n" "    pthread_mutex_unlock(&f->lock);\n" "    return f->result;\n" "}\n" "\n" "MXY_INLINE mxy_future *mxy_future_retain(mxy_future *f) {\n" "    if (f) mxy_rc_inc(&f->rc);\n" "    return f;\n" "}\n" "\n" "MXY_FN void mxy_future_release(mxy_future *f) {\n" "    if (!f || !mxy_rc_dec(&f->rc)) return;\n" "    pthread_mutex_lock(&f->lock);\n" "    int done = f->done;\n" "    if (!done) f->orphaned = 1;\n" "    pthread_mutex_unlock(&f->lock);\n" "    if (!done) {\n" "        pthread_detach(f->thread);\n" "        return;\n" "    }\n" "    if (done == 1) pthread_join(f->thread, NULL);\n" "    mxy_future_free(f);\n" "}\n" "\n" "MXY_FN void mxy_copy_future(void *dst, const void *src) { *(mxy_future **)dst = mxy_future_retain(*(mxy_future *const *)src); }\n" "MXY_FN void mxy_drop_future(void *p) { mxy_future_release(*(mxy_future **)p); }\n" "static const mxy_vw mxy_vw_future __attribute__((unused)) = {sizeof(mxy_future *), mxy_copy_future, mxy_drop_future, mxy_eq_ptr, mxy_hash_ptr, NULL, NULL, \"future\"};\n" "#else\n" "typedef struct mxy_future mxy_future;\n" "#endif\n" "\n" "static const mxy_vw mxy_vw_void __attribute__((unused)) = {0, NULL, NULL, NULL, NULL, NULL, NULL, \"void\"};\n" "/* moxy runtime: process arguments and assertion support */\n" "static int mxy_argc __attribute__((unused));\n" "static char **mxy_argv __attribute__((unused));\n" "\n" "MXY_FN mxy_list *mxy_args(void) {\n" "    mxy_list *l = mxy_list_new(&mxy_vw_str, mxy_argc);\n" "    for (int i = 0; i < mxy_argc; i++) {\n" "        mxy_str s = mxy_str_from(mxy_argv[i]);\n" "        mxy_list_push(&l, &mxy_vw_str, &s, 1);\n" "    }\n" "    return l;\n" "}\n" "\n" "MXY_FN MXY_NORETURN void mxy_assert_fail(const char *loc, const char *expr, mxy_str msg) {\n" "    fflush(stdout);\n" "    if (msg) fprintf(stderr, \"assertion failed: %s\\n  at %s\\n\", msg, loc);\n" "    else fprintf(stderr, \"assertion failed: %s\\n  at %s\\n\", expr, loc);\n" "    exit(1);\n" "}\n" "\n" "MXY_FN mxy_str mxy_read_line(void) {\n" "    mxy_buf b = {0};\n" "    int c;\n" "    int any = 0;\n" "    while ((c = fgetc(stdin)) != EOF) {\n" "        any = 1;\n" "        if (c == '\\n') break;\n" "        mxy_buf_putc(&b, (char)c);\n" "    }\n" "    if (!any) {\n" "        free(b.data);\n" "        return NULL;\n" "    }\n" "    if (b.len && b.data[b.len - 1] == '\\r') b.data[--b.len] = '\\0';\n" "    return mxy_str_from_buf(&b);\n" "}\n" "\n" "MXY_FN mxy_str mxy_read_file(mxy_str path, int *ok) {\n" "    FILE *f = path ? fopen(path, \"rb\") : NULL;\n" "    if (!f) {\n" "        *ok = 0;\n" "        return NULL;\n" "    }\n" "    mxy_buf b = {0};\n" "    char chunk[8192];\n" "    size_t n;\n" "    while ((n = fread(chunk, 1, sizeof(chunk), f)) > 0) mxy_buf_put(&b, chunk, (int64_t)n);\n" "    fclose(f);\n" "    *ok = 1;\n" "    return mxy_str_from_buf(&b);\n" "}\n" "\n" "MXY_FN bool mxy_write_file(mxy_str path, mxy_str data, const char *mode) {\n" "    FILE *f = path ? fopen(path, mode) : NULL;\n" "    if (!f) return false;\n" "    size_t n = (size_t)mxy_str_len(data);\n" "    bool ok = fwrite(data ? data : \"\", 1, n, f) == n;\n" "    return fclose(f) == 0 && ok;\n" "}\n" "";
static const StdEntry std_entries[7] = {{"std/debug.mxy", "// std/debug.mxy — markers for unfinished or impossible code.\n" "// panic(message) is built in.\n" "\n" "void todo(string what) {\n" "    panic(\"not yet implemented: \" + what);\n" "}\n" "\n" "void unreachable() {\n" "    panic(\"entered unreachable code\");\n" "}\n" ""}, {"std/io.mxy", "// std/io.mxy — console and file input/output\n" "extern string mxy_read_line();\n" "extern string mxy_read_file(string path, int *ok);\n" "extern bool mxy_write_file(string path, string data, const char *mode);\n" "\n" "void eprint(string msg) { fprintf(stderr, \"%s\\n\", msg); }\n" "void eprintln(string msg) { eprint(msg); }\n" "\n" "// the next line from standard input, or null at end of input\n" "string readln() { return mxy_read_line(); }\n" "\n" "Result<string> read_file(string path) {\n" "    int ok = 0;\n" "    string data = mxy_read_file(path, &ok);\n" "    if (!ok) { return Err(\"cannot read \\(path)\"); }\n" "    return Ok(data);\n" "}\n" "\n" "Result<void> write_file(string path, string data) {\n" "    if (!mxy_write_file(path, data, \"wb\")) { return Err(\"cannot write \\(path)\"); }\n" "    return Ok();\n" "}\n" "\n" "Result<void> append_file(string path, string data) {\n" "    if (!mxy_write_file(path, data, \"ab\")) { return Err(\"cannot append to \\(path)\"); }\n" "    return Ok();\n" "}\n" "\n" "string[] read_lines(string path) {\n" "    Result<string> text = read_file(path);\n" "    match text {\n" "        Ok(s) => return s.lines(),\n" "        Err(e) => return[],\n" "    }\n" "}\n" ""}, {"std/math.mxy", "// std/math.mxy — integer and floating point helpers. C's <math.h> is available too.\n" "#include <math.h>\n" "\n" "int abs_int(int x) { return x < 0 ? -x : x; }\n" "int min_int(int a, int b) { return a < b ? a : b; }\n" "int max_int(int a, int b) { return a > b ? a : b; }\n" "\n" "int clamp_int(int x, int lo, int hi) {\n" "    if (x < lo) { return lo; }\n" "    if (x > hi) { return hi; }\n" "    return x;\n" "}\n" "\n" "double min_float(double a, double b) { return a < b ? a : b; }\n" "double max_float(double a, double b) { return a > b ? a : b; }\n" "\n" "double clamp_float(double x, double lo, double hi) {\n" "    if (x < lo) { return lo; }\n" "    if (x > hi) { return hi; }\n" "    return x;\n" "}\n" "\n" "long gcd(long a, long b) {\n" "    if (a < 0) { a = -a; }\n" "    if (b < 0) { b = -b; }\n" "    while (b != 0) {\n" "        long t = a % b;\n" "        a = b;\n" "        b = t;\n" "    }\n" "    return a;\n" "}\n" "\n" "long pow_int(long base, int exp) {\n" "    long result = 1;\n" "    for _ in 0..exp { result *= base; }\n" "    return result;\n" "}\n" "\n" "int sum_ints(int[] xs) {\n" "    int total = 0;\n" "    for x in xs { total += x; }\n" "    return total;\n" "}\n" ""}, {"std/os.mxy", "// std/os.mxy — process arguments, environment and commands\n" "#include <stdlib.h>\n" "\n" "extern string[] mxy_args();\n" "\n" "// the command line, program name first\n" "string[] args() { return mxy_args(); }\n" "\n" "// an environment variable, or null when it is not set\n" "string env(string name) {\n" "    char *value = getenv(name);\n" "    if (!value) { return null; }\n" "    return string(value);\n" "}\n" "\n" "bool has_env(string name) { return getenv(name) != null; }\n" "\n" "// runs a shell command and returns its exit status\n" "int run(string command) {\n" "    int status = system(command);\n" "    if (status == -1) { return -1; }\n" "    return (status >> 8) & 255;\n" "}\n" ""}, {"std/string.mxy", "// std/string.mxy — helpers on top of the string methods\n" "// (s.len, s.contains(x), s.split(sep), s.trim(), s.upper(), s.replace(a, b), ...)\n" "\n" "int str_len(string s) { return (int)s.len; }\n" "bool str_eq(string a, string b) { return a == b; }\n" "bool str_contains(string haystack, string needle) { return haystack.contains(needle); }\n" "bool str_starts_with(string s, string prefix) { return s.starts_with(prefix); }\n" "bool str_ends_with(string s, string suffix) { return s.ends_with(suffix); }\n" "\n" "string join(string[] parts, string sep) { return parts.join(sep); }\n" "\n" "string pad_left(string s, int width, char fill) {\n" "    string out = s;\n" "    while (out.len < width) { out = string(fill) + out; }\n" "    return out;\n" "}\n" "\n" "string pad_right(string s, int width, char fill) {\n" "    string out = s;\n" "    while (out.len < width) { out = out + string(fill); }\n" "    return out;\n" "}\n" "\n" "string reverse(string s) {\n" "    string out = \"\";\n" "    for i in 0..s.len { out = out + string(s[s.len - 1 - i]); }\n" "    return out;\n" "}\n" "\n" "int count(string s, string sub) {\n" "    if (sub.len == 0) { return 0; }\n" "    return (int)s.split(sub).len - 1;\n" "}\n" ""}, {"std/test.mxy", "// std/test.mxy — assertions with readable failure messages.\n" "// assert(condition) and assert(condition, \"message\") are built in.\n" "\n" "void assert_eq_int(long got, long want) {\n" "    if (got != want) { panic(\"expected \\(want), got \\(got)\"); }\n" "}\n" "\n" "void assert_eq_float(double got, double want, double tolerance) {\n" "    double diff = got - want;\n" "    if (diff < 0) { diff = -diff; }\n" "    if (diff > tolerance) { panic(\"expected \\(want), got \\(got)\"); }\n" "}\n" "\n" "void assert_eq_str(string got, string want) {\n" "    if (got != want) { panic(\"expected \\\"\\(want)\\\", got \\\"\\(got)\\\"\"); }\n" "}\n" "\n" "void assert_true(bool cond) {\n" "    if (!cond) { panic(\"expected true\"); }\n" "}\n" "\n" "void assert_false(bool cond) {\n" "    if (cond) { panic(\"expected false\"); }\n" "}\n" ""}, {"std/time.mxy", "// std/time.mxy — clocks and sleeping\n" "#include <time.h>\n" "\n" "// milliseconds since the Unix epoch\n" "long now_ms() {\n" "    struct timespec ts;\n" "    clock_gettime(CLOCK_REALTIME, &ts);\n" "    return (long)ts.tv_sec * 1000 + (long)(ts.tv_nsec / 1000000);\n" "}\n" "\n" "// a monotonic clock for measuring durations, in milliseconds\n" "double monotonic_ms() {\n" "    struct timespec ts;\n" "    clock_gettime(CLOCK_MONOTONIC, &ts);\n" "    return (double)ts.tv_sec * 1000.0 + (double)ts.tv_nsec / 1000000.0;\n" "}\n" "\n" "void sleep_ms(long ms) {\n" "    struct timespec ts;\n" "    ts.tv_sec = ms / 1000;\n" "    ts.tv_nsec = (ms % 1000) * 1000000;\n" "    nanosleep(&ts, null);\n" "}\n" ""}};
